const entry = $('Split entries1').item.json;
const src = $input.item.json;

return {
  json: {
    miniflux_entry_id: entry.id,
    feed_id: entry.feed_id,
    url: entry.url,
    title: entry.title || '(no title)',
    author: entry.author || src.author_default || '',
    published_at: entry.published_at || null,
    rss_content_html: entry.content || entry.summary || '',
    source_id: src.source_id,
    source_name: src.source_name,
    category: src.category,
    source_priority: src.priority,
    fetch_full_content: src.fetch_full_content
  }
};

const stdout = $input.item.json.stdout || '{}';
const prep = $('Prepare entry1').item.json;

let extr;
try { extr = JSON.parse(stdout.trim()); } catch(e) { extr = { success: false }; }

const stripHtml = (html) => (html || '')
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<a[^>]+href="([^"]*)"[^>]*>([^<]*)<\/a>/gi, '[$2]($1)')
  .replace(/<\/?([a-z][a-z0-9]*)\b[^>]*>/gi, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/\s+/g, ' ').trim();

const rssStripped = stripHtml(prep.rss_content_html || '');

let markdown, contentSource;

if (extr.success && extr.markdown && extr.markdown.length > 100) {
  markdown = extr.markdown;
  contentSource = 'trafilatura';
} else if (rssStripped.length > 100) {
  markdown = rssStripped;
  contentSource = 'rss';
} else {
  markdown = rssStripped || '';
  contentSource = 'none';
}

return {
  json: {
    ...prep,
    full_content_markdown: markdown,
    full_content_source: contentSource,
    full_content_char_count: markdown.length,
    content_truncated: false,
    resolved_title: prep.title
  }
};

